 use callisto_model::{CommandError, CommandOutput, CommandRunner};
+
+#[test]
+fn release_unit_defaults_and_both_raw_override_forms_are_closed() {
+    use callisto_graph::config::{is_release_unit, load, ReleaseUnitClassification};
+    let tmp = tempfile::tempdir().unwrap();
+    let id = callisto_model::PackageId::parse("cargo/alpha").unwrap();
+    assert!(is_release_unit(&load(tmp.path()).unwrap(), &id).unwrap());
+    for block in ["package", "package-set"] {
+        for (value, expected) in [("releasable", true), ("dev-only", false)] {
+            fs::write(tmp.path().join("callisto.toml"), format!("[[{block}]]\nmatch = \"alpha\"\nrelease-unit = \"{value}\"\n")).unwrap();
+            let cfg = load(tmp.path()).unwrap();
+            assert_eq!(is_release_unit(&cfg, &id).unwrap(), expected);
+            let resolved = if block == "package" { &cfg.packages[0].1 } else { &cfg.package_sets[0].1 };
+            assert_eq!(resolved.release_unit, Some(if expected { ReleaseUnitClassification::Releasable } else { ReleaseUnitClassification::DevOnly }));
+        }
+        fs::write(tmp.path().join("callisto.toml"), format!("[[{block}]]\nmatch = \"alpha\"\nrelease-unit = \"private\"\n")).unwrap();
+        let error = load(tmp.path()).unwrap_err().to_string();
+        assert!(error.contains("release-unit") && error.contains("releasable or dev-only"), "{error}");
+        fs::write(tmp.path().join("callisto.toml"), format!("[[{block}]]\nmatch = \"alpha\"\nrelease-units = \"dev-only\"\n")).unwrap();
+        assert!(load(tmp.path()).is_err());
+    }
+}
+
+#[test]
+fn release_unit_uses_one_effective_override_after_discovery() {
+    use callisto_graph::{config::is_release_unit, DependencyResolver};
+    let tmp = tempfile::tempdir().unwrap();
+    write_two_crate_workspace(tmp.path(), "alpha", "beta");
+    // Prefixed exact beats bare exact; an exact block with no classification
+    // owns the whole override and defaults to releasable. Package-set fallback
+    // uses discovered ecosystems for the bare IDs returned by discovery.
+    for (config, alpha, beta) in [
+        ("[[package-set]]\nmatch = 'cargo:*'\nrelease-unit = 'dev-only'\n", false, false),
+        ("[[package]]\nmatch = 'alpha'\nrelease-unit = 'dev-only'\n[[package]]\nmatch = 'cargo/alpha'\nrelease-unit = 'releasable'\n[[package-set]]\nmatch = 'cargo:*'\nrelease-unit = 'dev-only'\n", true, false),
+        ("[[package]]\nmatch = 'alpha'\n[[package-set]]\nmatch = 'cargo:*'\nrelease-unit = 'dev-only'\n", true, false),
+        ("[[package-set]]\nmatch = 'npm:*'\nrelease-unit = 'dev-only'\n[[package-set]]\nmatch = 'cargo:*'\nrelease-unit = 'releasable'\n[[package-set]]\nmatch = '*'\nrelease-unit = 'dev-only'\n", true, true),
+    ] {
+        fs::write(tmp.path().join("callisto.toml"), config).unwrap();
+        let ws = Workspace::load(tmp.path().to_path_buf(), &IgnoreWalkLocator::new(tmp.path()), &NoopRunner).unwrap();
+        for package in ws.graph.packages() {
+            assert_eq!(is_release_unit(&ws.config, &package.id).unwrap(), if package.id.name() == "alpha" { alpha } else { beta }, "{config}: {}", package.id);
+        }
+    }
+}
