 use std::cell::OnceCell;
+
+mod real_release_units {
+    use std::{fs, io::Write, path::Path, process::{Command, Stdio}};
+    use callisto_graph::{
+        apply::{apply_version_plan, ApplyOptions},
+        commands::{derive_release_commit_decision, derive_release_decision, derive_selected_release_decision, plan_version, VersionOptions},
+        config::is_release_unit, infer::NoInference, locate::IgnoreWalkLocator, DependencyResolver, Workspace,
+    };
+    use callisto_model::{ApplyPermit, CommandError, CommandOutput, CommandRunner, CommitSha, Ecosystem, ReleaseDecisionEntry, ReleaseDecisionV1, ReleaseInclusionReason, ReleasePackageId};
+
+    struct GitRunner;
+    impl CommandRunner for GitRunner {
+        fn run(&self, program: &str, args: &[&str], cwd: &Path) -> Result<CommandOutput, CommandError> {
+            self.run_with_stdin(program, args, cwd, &[])
+        }
+
+        fn run_with_stdin(&self, program: &str, args: &[&str], cwd: &Path, input: &[u8]) -> Result<CommandOutput, CommandError> {
+            assert_eq!(program, "git", "this test must never invoke a registry or build command");
+            let mut child = Command::new(program).args(args).current_dir(cwd)
+                .env("GIT_CONFIG_NOSYSTEM", "1").env("GIT_CONFIG_GLOBAL", "/dev/null")
+                .stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();
+            child.stdin.take().unwrap().write_all(input).unwrap();
+            let result = child.wait_with_output().unwrap();
+            Ok(CommandOutput { exit_code: result.status.code(), stdout: String::from_utf8(result.stdout).unwrap(), stderr: String::from_utf8(result.stderr).unwrap() })
+        }
+    }
+
+    fn git(root: &Path, args: &[&str]) -> String {
+        let result = GitRunner.run("git", args, root).unwrap();
+        assert!(result.success(), "{args:?}: {}", result.stderr);
+        result.stdout.trim().to_owned()
+    }
+
+    /// Copy the actual repository membership, package manifests and policy,
+    /// rather than constructing a second hand-maintained Callisto roster.
+    fn copy_repository_manifests(root: &Path) {
+        let repo = Path::new(env!("CARGO_MANIFEST_DIR")).parent().unwrap().parent().unwrap();
+        for name in ["Cargo.toml", "callisto.toml"] {
+            fs::copy(repo.join(name), root.join(name)).unwrap();
+        }
+        for entry in fs::read_dir(repo.join("crates")).unwrap() {
+            let entry = entry.unwrap();
+            if !entry.path().join("Cargo.toml").is_file() { continue; }
+            let dest = root.join("crates").join(entry.file_name());
+            fs::create_dir_all(&dest).unwrap();
+            for name in ["Cargo.toml", "CHANGELOG.md"] {
+                let source = entry.path().join(name);
+                if source.is_file() { fs::copy(source, dest.join(name)).unwrap(); }
+            }
+        }
+        fs::create_dir_all(root.join(".changeset")).unwrap();
+        fs::write(root.join(".changeset/train.md"), "---\n\"callisto-model\": patch\n---\n\nCoordinate the product train.\n").unwrap();
+        git(root, &["init", "-q"]);
+        git(root, &["config", "user.name", "Release test"]);
+        git(root, &["config", "user.email", "release-test@example.invalid"]);
+        git(root, &["add", "."]);
+        git(root, &["commit", "-qm", "base"]);
+    }
+
+    #[test]
+    fn real_callisto_train_keeps_fixture_source_bump_outside_durable_authority() {
+        for tamper in ["none", "fixture-entry", "fixture-target", "unclaimed-package"] {
+            let dir = tempfile::tempdir().unwrap();
+            let root = dir.path();
+            copy_repository_manifests(root);
+            let locator = IgnoreWalkLocator::new(root);
+            let ws = Workspace::load(root.to_path_buf(), &locator, &GitRunner).unwrap();
+            let fixture = ws.graph.packages().find(|package| package.id.name() == "callisto-fixtures").unwrap();
+            assert!(!is_release_unit(&ws.config, &fixture.id).unwrap());
+            let plan = plan_version(&ws, &NoInference, &VersionOptions::default()).unwrap();
+            assert!(!plan.diagnostics.iter().any(|diagnostic| diagnostic.severity == callisto_model::DiagnosticSeverity::Error), "{:?}", plan.diagnostics);
+            let source_bump = plan.bumps.iter().find(|bump| bump.package == fixture.id).unwrap();
+            let fixture_target = source_bump.to.clone();
+            assert!(source_bump.writes.iter().any(|write| matches!(write, callisto_graph::plan::VersionWriteTarget::Manifest(path) if path == Path::new("crates/callisto-fixtures/Cargo.toml"))));
+            assert!(!plan.changelog_writes.iter().any(|write| write.changelog_path.starts_with("crates/callisto-fixtures")));
+            let mut decision = derive_release_decision(&ws, &plan).unwrap();
+            assert_eq!(decision.entries.len(), ws.graph.packages().count() - 1);
+            assert!(decision.entries.iter().all(|entry| entry.package.name() != "callisto-fixtures" && entry.target_version == fixture_target));
+            let fixture_id = ReleasePackageId::new(Ecosystem::Cargo, "callisto-fixtures").unwrap();
+            assert!(derive_selected_release_decision(&ws, &plan, &[fixture_id.clone()]).is_err());
+            if tamper == "fixture-entry" {
+                let mut entries = decision.entries;
+                entries.push(ReleaseDecisionEntry { package: fixture_id, target_version: fixture_target.clone(), reasons: vec![ReleaseInclusionReason::ExplicitSelection] });
+                decision = ReleaseDecisionV1::new(entries).unwrap();
+            } else if tamper == "unclaimed-package" {
+                decision = ReleaseDecisionV1::new(decision.entries.into_iter().filter(|entry| entry.package.name() != "callisto-format").collect()).unwrap();
+            }
+            apply_version_plan(root, &plan, &GitRunner, &ApplyOptions::default(), &ApplyPermit::force_for_tests()).unwrap();
+            drop(ws);
+            if tamper == "fixture-target" {
+                let path = root.join("crates/callisto-fixtures/Cargo.toml");
+                let mut manifest: toml_edit::DocumentMut = fs::read_to_string(&path).unwrap().parse().unwrap();
+                manifest["package"]["version"] = toml_edit::value("99.0.0");
+                callisto_model::atomic::atomic_write(&path, manifest.to_string().as_bytes()).unwrap();
+            }
+            fs::create_dir_all(root.join(".callisto")).unwrap();
+            let decision_path = Path::new(".callisto/release-decision.json");
+            fs::write(root.join(decision_path), serde_json::to_vec(&decision).unwrap()).unwrap();
+            git(root, &["add", "."]);
+            git(root, &["commit", "-qm", "version train"]);
+            let commit = CommitSha::parse(&git(root, &["rev-parse", "HEAD"])).unwrap();
+            let ws = Workspace::load(root.to_path_buf(), &locator, &GitRunner).unwrap();
+            let verified = derive_release_commit_decision(&ws, &commit, decision_path);
+            if tamper == "none" {
+                assert_eq!(verified.unwrap(), decision);
+            } else {
+                assert!(verified.is_err(), "accepted {tamper}");
+            }
+        }
+    }
+}
*** End Patch"));
